#!/usr/bin/env sh
# Senzu Theme for fzf: Senzu Tera Light
# Generated by senzu
#
# Source this file in your shell rc to apply (zsh/bash):
#
#   [ -f ~/.config/fzf/senzu-tera-light.sh ] && . ~/.config/fzf/senzu-tera-light.sh
#
# It appends the Senzu --color spec to FZF_DEFAULT_OPTS, preserving any other
# fzf options you set. To switch variants, source a different senzu fzf file
# instead (fzf merges --color flags, last one wins per element).

export FZF_DEFAULT_OPTS="${FZF_DEFAULT_OPTS:+$FZF_DEFAULT_OPTS }--color=fg:#1a2c2f,bg:#eaf8fb,hl:#9b4b28,fg+:#1a2c2f,bg+:#afd5da,hl+:#9b4b28,info:#2b647a,border:#c7d8da,prompt:#2b647a,pointer:#037a8f,marker:#48716e,spinner:#9c4d6d,header:#4e686d,gutter:#afd5da,preview-fg:#1a2c2f,preview-bg:#eaf8fb"
